sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_pSize;
uniform float amzp_pal;
uniform float amzp_levels;
uniform float amzp_count;
layout(color) uniform half4 amzp_c1;
layout(color) uniform half4 amzp_c2;
layout(color) uniform half4 amzp_c3;
layout(color) uniform half4 amzp_c4;
layout(color) uniform half4 amzp_c5;
layout(color) uniform half4 amzp_c6;
layout(color) uniform half4 amzp_c7;
layout(color) uniform half4 amzp_c8;
uniform float amzp_dither;
uniform float amzp_dAmt;
uniform float amzp_contrast;
uniform float amzp_sat;
uniform float amzp_outline;
uniform float amzp_grid;
uniform float amzp_scan;
uniform float amzp_alphaSteps;
uniform float amzp_mixAmt;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 at(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
    float bayer2(float2 c) { float2 m = mod(c, 2.0); return (m.x + 2.0 * m.y == 0.0) ? 0.0 : (m.x + 2.0 * m.y == 1.0 ? 2.0 : (m.x + 2.0 * m.y == 2.0 ? 3.0 : 1.0)); }
    float bayer4(float2 c) {
        float2 m = mod(c, 4.0);
        float a = bayer2(m);
        float b = bayer2(floor(m / 2.0));
        return a * 4.0 + b;
    }
    float thr(float2 c) {
        if (int(amzp_dither) == 1) return (bayer2(c) + 0.5) / 4.0 - 0.5;
        if (int(amzp_dither) == 2) return (bayer4(c) + 0.5) / 16.0 - 0.5;
        if (int(amzp_dither) == 3) return hh(c) - 0.5;
        return 0.0;
    }
    float3 palC(int i) {
        if (i == 0) return amzp_c1.rgb; if (i == 1) return amzp_c2.rgb; if (i == 2) return amzp_c3.rgb; if (i == 3) return amzp_c4.rgb;
        if (i == 4) return amzp_c5.rgb; if (i == 5) return amzp_c6.rgb; if (i == 6) return amzp_c7.rgb; return amzp_c8.rgb;
    }
    float dist2(float3 a, float3 b) { float3 d = a - b; return dot(d * d, float3(0.3, 0.59, 0.11)); }
    float3 look(float3 c) {
        float L = dot(c, float3(0.299, 0.587, 0.114));
        c = mix(float3(L), c, amzp_sat);
        return clamp((c - 0.5) * amzp_contrast + 0.5, 0.0, 1.0);
    }
    void nmFxMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 src = at(uv);
        float ps = max(floor(amzp_pSize + 0.5), 1.0);
        float2 cell = floor(uv * W / ps);
        float2 cuv = (cell + 0.5) * ps / W;
        float4 c = at(cuv);
        float a = c.a;
        float3 col = a > 0.0001 ? look(c.rgb / a) : float3(0.0);
        float t = thr(cell) * amzp_dAmt;
        float3 q;
        if (int(amzp_pal) == 1) {
            int n = int(clamp(floor(amzp_count + 0.5), 2.0, 8.0));
            float b1 = 1e9, b2 = 1e9;
            float3 p1 = float3(0.0), p2 = float3(0.0);
            for (int i = 0; i < 8; i++) {
                if (i >= n) break;
                float3 pc = palC(i);
                float d = dist2(col, pc);
                if (d < b1) { b2 = b1; p2 = p1; b1 = d; p1 = pc; }
                else if (d < b2) { b2 = d; p2 = pc; }
            }
            float r = sqrt(b1) / max(sqrt(b1) + sqrt(b2), 1e-5);
            q = (r + t * 0.9 > 0.5 && int(amzp_dither) != 0) ? p2 : p1;
            if (int(amzp_dither) == 0) q = p1;
        } else {
            float lv = max(floor(amzp_levels + 0.5), 2.0) - 1.0;
            if (int(amzp_pal) == 2) col = float3(dot(col, float3(0.299, 0.587, 0.114)));
            q = clamp(floor(col * lv + 0.5 + t), 0.0, lv) / lv;
        }
        if (amzp_outline > 0.0) {
            float4 nx = at((cell + float2(1.5, 0.5)) * ps / W);
            float4 ny = at((cell + float2(0.5, 1.5)) * ps / W);
            float dd = max(abs(nx.a - a), abs(ny.a - a));
            float3 cxx = nx.a > 0.0001 ? nx.rgb / nx.a : float3(0.0);
            float3 cyy = ny.a > 0.0001 ? ny.rgb / ny.a : float3(0.0);
            dd = max(dd, max(length(cxx - col), length(cyy - col)) * 0.8);
            q *= 1.0 - amzp_outline * smoothstep(0.25, 0.6, dd);
        }
        float2 inC = fract(uv * W / ps);
        if (amzp_grid > 0.0 && ps >= 3.0) {
            float amzSource_gl = step(inC.x, 1.0 / ps) + step(inC.y, 1.0 / ps);
            q *= 1.0 - amzp_grid * 0.6 * clamp(amzSource_gl, 0.0, 1.0);
        }
        if (amzp_scan > 0.0) q *= 1.0 - amzp_scan * 0.5 * step(0.5, mod(cell.y, 2.0));
        float oa = mix(a, step(0.5, a), clamp(amzp_alphaSteps, 0.0, 1.0));
        float4 res = float4(q * oa, oa);
        amzOutput = mix(src, res, clamp(amzp_mixAmt, 0.0, 1.0));
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
